import unittest
import json
from cli.app import run_cli

class TestCLI(unittest.TestCase):
    def test_json_flag(self):
        out = run_cli(["--json"])
        d = json.loads(out)
        self.assertEqual(d["status"], "ok")

if __name__ == '__main__': unittest.main()
